<script>
(()=>{const nav=document.querySelector('[data-s603-nav]');document.querySelector('[data-s603-menu]')?.addEventListener('click',()=>nav?.classList.toggle('is-open'));
document.querySelectorAll('[data-s603-slider]').forEach(slider=>{const slides=[...slider.querySelectorAll('[data-s603-slide]')],dots=[...slider.querySelectorAll('[data-s603-dot]')];if(slides.length<2)return;let index=0;const show=next=>{slides[index]?.classList.remove('is-active');dots[index]?.classList.remove('is-active');index=(next+slides.length)%slides.length;slides[index]?.classList.add('is-active');dots[index]?.classList.add('is-active')};dots.forEach((dot,i)=>dot.addEventListener('click',()=>show(i)));setInterval(()=>show(index+1),Math.max(2600,Number(slider.dataset.autoplay||6000)))});
document.querySelectorAll('[data-s603-carousel]').forEach(carousel=>{const track=carousel.querySelector('[data-s603-track]'),cards=[...(track?.children||[])];if(cards.length<2)return;let index=0;const visible=()=>innerWidth<620?1:innerWidth<920?2:innerWidth<1280?3:5;setInterval(()=>{const count=visible();index=(index+1)%Math.max(1,cards.length-count+1);track.style.transform=`translateX(-${index*(100/count)}%)`},Math.max(2600,Number(carousel.dataset.autoplay||3600)))});})();
</script>
